import {ToolRegistry} from './registry.js';

describe('ToolRegistry input validation', () => {
  // spec: specs/hal-engine-tool-input-validation#1
  it('returns a rejection for missing required input without invoking the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;

    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      resultNamesRequiredLocation: /location.*required/i.test(response.result),
      executorCalls,
    }).toEqual({resultNamesRequiredLocation: true, executorCalls: 0});
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('reports the expected type for a rejected property without exposing its value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'lookup_record',
        description: 'Look up a record by identifier',
        inputSchema: {
          type: 'object',
          properties: {identifier: {type: 'string'}},
          required: ['identifier'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('lookup_record', {identifier: 123456789});

    expect({
      resultNamesFieldAndType: response.result.includes('identifier') && response.result.includes('string'),
      leaksValue: response.result.includes('123456789'),
      executorCalls,
    }).toEqual({resultNamesFieldAndType: true, leaksValue: false, executorCalls: 0});
  });
});
